_cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <vector>
#include <limits>

template <typename scalar_t>
__global__ void maxpool1d_forward_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    int64_t* __restrict__ indices,
    int N,
    int C,
    int L,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    int out_len)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * out_len;
    if (idx >= total) return;

    int n = idx / (C * out_len);
    int rem = idx % (C * out_len);
    int c = rem / out_len;
    int o = rem % out_len;

    int start = o * stride - padding;
    float max_val = -3.4e38f;               // -FLT_MAX
    int64_t max_idx = -1;

    #pragma unroll
    for (int k = 0; k < kernel_size; ++k) {
        int in_idx = start + k * dilation;
        float val = 0.0f;                   // padded value (zero)
        if (in_idx >= 0 && in_idx < L) {
            val = __half2float(input[((int64_t)n * C + c) * L + in_idx]);
        }
        if (val > max_val) {
            max_val = val;
            max_idx = in_idx;
        }
    }

    output[idx] = __float2half(max_val);
    if (indices != nullptr) {
        indices[idx] = max_idx;
    }
}

std::vector<torch::Tensor> maxpool1d_forward(
    torch::Tensor input,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    bool return_indices)
{
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == at::ScalarType::Half,
                "input must be of type torch.float16");

    const int64_t N = input.size(0);
    const int64_t C = input.size(1);
    const int64_t L = input.size(2);

    const int64_t out_len = (L + 2 * padding -
                             dilation * (kernel_size - 1) - 1) / stride + 1;

    auto opts = torch::TensorOptions()
                    .dtype(at::ScalarType::Half)
                    .device(input.device());
    torch::Tensor output = torch::empty({N, C, out_len}, opts);
    torch::Tensor indices;
    int64_t* idx_ptr = nullptr;

    if (return_indices) {
        indices = torch::empty({N, C, out_len},
                               torch::TensorOptions()
                                   .dtype(at::ScalarType::Long)
                                   .device(input.device()));
        idx_ptr = indices.data_ptr<int64_t>();
    }

    const int threads = 256;
    const int blocks = (N * C * out_len + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "maxpool1d_forward_kernel", [&] {
        maxpool1d_forward_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            idx_ptr,
            static_cast<int>(N),
            static_cast<int>(C),
            static_cast<int>(L),
            kernel_size,
            stride,
            padding,
            dilation,
            static_cast<int>(out_len));
    });

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }

    if (return_indices) {
        return {output, indices};
    } else {
        return {output};
    }
}

