    m.def("maxpool1d_forward", &maxpool1d_forward,
          "1‑D max‑pooling forward (CUDA, fp16)");
}
'''

# compile the extension
_maxpool_ext = load_inline(name='maxpool1d_cuda',
                           cpp_sources=_cuda_src,
