                 kernel_size: int,
                 stride: int = None,
                 padding: int = 0,
                 dilation: int = 1,
                 return_indices: bool = False):
        super(ModelNew, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding
        self.dilation = dilation
        self.return_indices = return_indices

    def forward(self, x: torch.Tensor):
        """
        Apply 1‑D max‑pooling using the compiled CUDA kernel.

        Args:
            x (torch.Tensor): (N, C, L) fp16 tensor on CUDA.

        Returns:
            torch.Tensor or (torch.Tensor, torch.LongTensor) depending on
            return_indices.
        """
        out = _maxpool_ext.maxpool1d_forward(
            x,
            self.kernel_size,
            self.stride,
            self.padding,
            self.dilation,
            self.return_indices)

        if self.return_indices:
            return out[0], out[1]
        else:
            return out[0]

